package net.minecraft.client.renderer;import java.util.*;import net.minecraft.resources.ResourceLocation;public class RenderType{Object format;public State state;public RenderType(Object f){format=f;}public RenderType(ResourceLocation texture){format=com.mojang.blaze3d.vertex.DefaultVertexFormat.NEW_ENTITY;state=new State(texture);}public Object format(){return format;}public static RenderType entityCutoutNoCull(ResourceLocation id){return new RenderType(id);}public static class State{public Texture textureState;State(ResourceLocation id){textureState=new Texture(id);}}public static class Texture{final ResourceLocation id;Texture(ResourceLocation t){id=t;}public Optional<ResourceLocation>cutoutTexture(){return Optional.of(id);}}}
